@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#172950;--blue:#314d80;--cream:#fff8e9;--gold:#ffcf63;--coral:#ff786e;--mint:#78d6b1}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#172950;color:var(--cream)}body{font-family:'Space Grotesk',sans-serif;display:flex;justify-content:center;align-items:center;padding:24px;background:radial-gradient(ellipse at 50% 0%,#263d6a,#172950 75%);overflow-x:hidden}.game-shell{width:min(1120px,100%);margin:auto}.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;padding:0 6px 15px}.brand{display:flex;align-items:center;gap:8px;color:#fff4d8;text-decoration:none;font-family:'Press Start 2P',monospace;font-size:9px;line-height:1.55;letter-spacing:-.3px}.brand-mark{color:var(--gold);font-size:27px;text-shadow:0 0 16px #ffc55c}.world-label{font:500 11px 'DM Mono',monospace;letter-spacing:2px;color:#a8b7d4;display:flex;gap:12px;align-items:center}.world-dot{width:7px;height:7px;background:var(--mint);border-radius:50%;box-shadow:0 0 10px var(--mint)}.world-stage{border-left:1px solid #536486;padding-left:13px;color:#7387ae}.sound-toggle{border:1px solid #3b527c;border-radius:20px;background:#1b3058;color:#ffd46e;padding:8px 13px;font:10px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.sound-toggle span{color:#c1cde0;margin-left:5px}.game-frame{position:relative;border:1px solid #52668d;border-radius:12px;overflow:hidden;background:#5d9de4;box-shadow:0 24px 80px #080f2359,0 0 0 5px #213761,0 0 0 6px #52668d}.game-hud{position:absolute;z-index:2;top:0;left:0;right:0;height:74px;padding:12px 25px;display:grid;grid-template-columns:1fr .8fr 1.7fr .8fr .7fr;align-items:center;background:linear-gradient(180deg,#172748eF,#172748bb 78%,transparent);pointer-events:none}.hud-item{display:grid;grid-template-columns:auto auto;column-gap:8px;align-items:center;justify-content:start}.hud-icon{grid-row:span 2;font-size:20px;color:#ffd257;text-shadow:0 0 10px #ffc244}.coin-icon{width:12px;height:16px;grid-row:span 2;border-radius:50%;border:2px solid #ffe897;background:#ffb936;box-shadow:inset 2px 0 #e88c2e}.hud-caption{font:9px 'DM Mono',monospace;letter-spacing:1.4px;color:#afbdd5}.hud-item b{font:14px 'DM Mono',monospace;letter-spacing:1px;color:#fff6dd}.coin-item{margin-left:10px}.hud-center{text-align:center;display:flex;flex-direction:column;gap:5px}.level-name{font:10px 'Press Start 2P',monospace;color:#fff2cf;text-shadow:1px 2px #172950;letter-spacing:.3px}.level-sub{font:8px 'DM Mono',monospace;letter-spacing:2px;color:#c5d5ed}.lives-item{justify-self:center;display:flex;flex-direction:column;gap:4px}.lives-item b{font-size:13px;color:#ff8882;white-space:nowrap;letter-spacing:2px}.time-item{justify-self:end;display:flex;flex-direction:column;gap:4px}.time-item b{font-size:17px;color:#fff3d4}#game{display:block;width:100%;height:auto;aspect-ratio:16/9;image-rendering:pixelated;background:#75b9f1}.game-footer{height:37px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;background:#1c3157;color:#9aaccb;font:9px 'DM Mono',monospace;letter-spacing:.65px}.game-footer b{color:#ffd26e}.game-footer>span:first-child{color:#d1dded}.game-footer i{font-style:normal;color:#e3c16e}.page-footer{display:flex;justify-content:space-between;padding:20px 4px;color:#60749a;font:9px 'DM Mono',monospace;letter-spacing:1.4px}.page-footer b{color:#f4c660}.overlay{position:absolute;z-index:3;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#14244735,#14244705,#14244745);transition:opacity .25s,visibility .25s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{width:min(485px,82%);text-align:center;padding:32px 28px 25px;background:#21385fe8;border:1px solid #b5c3c75e;border-radius:9px;box-shadow:0 15px 50px #10203a72, inset 0 1px #ffffff22;position:relative;overflow:hidden}.overlay-card:before,.overlay-card:after{content:'';position:absolute;width:130px;height:130px;border:1px solid #ffd66c2b;transform:rotate(45deg);pointer-events:none}.overlay-card:before{left:-95px;top:-95px}.overlay-card:after{right:-95px;bottom:-95px}.eyebrow{font:9px 'DM Mono',monospace;color:#d4e0ea;letter-spacing:2.5px}.eyebrow span{color:#ffd15f;margin:0 9px}.overlay h1{font:30px/1.45 'Press Start 2P',monospace;letter-spacing:-1px;margin:17px 0 14px;color:#fff3cd;text-shadow:3px 4px #b15a53}.overlay h1 em{font-style:normal;color:#ffd05c;text-shadow:3px 4px #bc743d}.story{font:16px/1.6 'Space Grotesk',sans-serif;color:#c7d5e7;margin:0 0 21px}.primary-button{position:relative;border:0;border-bottom:4px solid #c47937;border-radius:5px;background:linear-gradient(#ffdc79,#ffba50);color:#553c37;padding:15px 23px;font:11px 'Press Start 2P',monospace;cursor:pointer;box-shadow:0 5px 20px #ffc25430;transition:transform .15s,filter .15s}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.07)}.primary-button:active{transform:translateY(2px);border-bottom-width:2px}.primary-button span{font-size:12px;margin-right:8px}.controls-note{margin-top:19px;color:#aabbce;font:9px 'DM Mono',monospace;letter-spacing:.6px}.controls-note span{color:#ffdc81}.controls-note i{color:#758aab;font-style:normal;padding:0 5px}.menu-foot{margin-top:16px;color:#8296b5;font:8px 'DM Mono',monospace;letter-spacing:1.1px}.touch-controls{position:absolute;z-index:2;left:20px;right:20px;bottom:18px;display:none;justify-content:space-between;pointer-events:none}.touch-dpad,.touch-actions{display:flex;gap:12px}.touch-controls button{pointer-events:auto;width:54px;height:54px;border:1px solid #fff8;border-radius:50%;background:#1b315b99;color:#fff4d8;font:19px 'Press Start 2P',monospace;touch-action:none;user-select:none;box-shadow:0 3px 10px #15294b50}.touch-actions button{background:#e783718f}.touch-actions button:first-child{background:#f2bc4c99}.touch-controls button.pressed{transform:scale(.94);background:#ffd264d9;color:#273859}@media(max-width:700px){body{padding:10px;align-items:flex-start}.topbar{height:50px;padding-bottom:10px}.brand{font-size:7px}.world-label{font-size:8px;letter-spacing:1px;gap:7px}.world-stage{padding-left:7px}.sound-toggle{font-size:8px;padding:7px}.game-hud{height:57px;padding:9px 10px;grid-template-columns:1fr .7fr 1.5fr .65fr .55fr}.hud-caption{font-size:7px;letter-spacing:.8px}.hud-item b{font-size:10px}.hud-icon{font-size:15px}.coin-icon{width:9px;height:13px;border-width:1px}.coin-item{margin-left:0}.level-name{font-size:7px}.level-sub{font-size:6px;letter-spacing:1px}.lives-item b{font-size:10px;letter-spacing:0}.time-item b{font-size:12px}.game-footer{height:30px;padding:0 9px;font-size:7px;letter-spacing:0}.footer-controls{display:none}.page-footer{font-size:7px;padding:14px 2px}.overlay-card{padding:24px 16px 19px;width:88%}.overlay h1{font-size:22px;margin:13px 0}.eyebrow{font-size:7px}.story{font-size:13px;margin-bottom:15px}.primary-button{padding:13px;font-size:9px}.controls-note{font-size:8px;margin-top:14px}.menu-foot{font-size:6px;margin-top:12px}.touch-controls{display:flex;bottom:14px}.touch-controls button{width:46px;height:46px;font-size:14px}.overlay:not(.hidden)~.touch-controls{display:none}}@media(max-width:440px){.world-label{font-size:7px;letter-spacing:.4px}.world-stage{font-size:6px}.sound-toggle span{display:none}.topbar{height:43px}.game-footer>span:first-child{font-size:6px}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=540,GROUND=458,LEVEL=6100,GRAVITY=1750;
const ui={overlay:document.getElementById('overlay'),card:document.getElementById('overlayCard'),button:document.getElementById('primaryButton'),score:document.getElementById('score'),coins:document.getElementById('coins'),lives:document.getElementById('lives'),time:document.getElementById('time'),sound:document.getElementById('soundToggle')};
let mode='menu',last=0,camera=0,score=0,coinCount=0,lives=3,timeLeft=300,muted=false,audio=null,worldTime=0,screenMessage='',messageTimer=0;
const keys={left:false,right:false,run:false,jump:false};
const player={x:75,y:GROUND-38,w:28,h:38,vx:0,vy:0,grounded:false,facing:1,coinsBoost:0,invuln:0,anim:0};
let platforms=[],blocks=[],coins=[],enemies=[],powerups=[],particles=[],clouds=[];
const rect=(x,y,w,h)=>({x,y,w,h});
function buildWorld(){
  platforms=[rect(0,GROUND,660,100),rect(760,GROUND,650,100),rect(1510,GROUND,690,100),rect(2300,GROUND,780,100),rect(3190,GROUND,720,100),rect(4040,GROUND,710,100),rect(4860,GROUND,1240,100)];
  // Floating ledges, stairs and little routes across each stretch.
  [[230,355,124],[415,295,112],[570,365,92],[880,350,112],[1050,285,112],[1238,350,114],[1570,345,126],[1760,285,110],[1930,360,112],[2390,350,108],[2555,290,105],[2720,230,105],[2860,345,115],[3280,350,110],[3450,290,110],[3630,350,112],[4140,350,110],[4310,290,112],[4490,350,110],[4970,350,110],[5150,290,108],[5335,350,110],[5520,280,112]].forEach(([x,y,w])=>platforms.push(rect(x,y,w,20)));
  // Pipes are solid scenery/collision ledges.
  const pipes=[{x:680,w:58,h:72},{x:1370,w:64,h:105},{x:2210,w:62,h:80},{x:3100,w:72,h:112},{x:3950,w:62,h:76},{x:4770,w:68,h:100}];
  pipes.forEach(p=>platforms.push(rect(p.x,GROUND-p.h,p.w,p.h)));
  blocks=[];
  [[278,355,'?'],[314,355,'b'],[455,295,'?'],[920,350,'?'],[1090,285,'?'],[1635,345,'?'],[1797,285,'?'],[2475,350,'?'],[2600,290,'?'],[3335,350,'?'],[3500,290,'?'],[4200,350,'?'],[4370,290,'?'],[5060,350,'?'],[5230,290,'?']].forEach(([x,y,type])=>blocks.push({x,y,w:34,h:34,type,used:false,bump:0}));
  coins=[];const addCoin=(x,y)=>coins.push({x,y,r:10,taken:false,phase:Math.random()*6});
  [[185,400],[233,315],[271,315],[309,315],[416,255],[455,255],[494,255],[568,325],[826,405],[880,310],[920,310],[960,310],[1050,245],[1090,245],[1130,245],[1240,310],[1515,410],[1570,305],[1610,305],[1650,305],[1760,245],[1800,245],[1840,245],[1970,320],[2370,410],[2390,310],[2430,310],[2470,310],[2555,250],[2595,250],[2635,250],[2720,190],[2860,305],[2900,305],[3210,410],[3280,310],[3320,310],[3360,310],[3450,250],[3490,250],[3530,250],[3630,310],[4060,410],[4140,310],[4180,310],[4220,310],[4310,250],[4350,250],[4390,250],[4490,310],[4910,410],[4970,310],[5010,310],[5050,310],[5150,250],[5190,250],[5230,250],[5335,310],[5520,240],[5560,240],[5600,240]].forEach(([x,y])=>addCoin(x,y));
  enemies=[];[510,990,1290,1840,2040,2460,2790,3500,3740,4260,4580,5090,5390].forEach((x,i)=>enemies.push({x,y:GROUND-30,w:32,h:30,vx:(i%2?1:-1)*48,min:x-90,max:x+90,alive:true,squash:0}));
  powerups=[];particles=[];clouds=[];for(let i=0;i<18;i++)clouds.push({x:i*420+Math.random()*220,y:55+Math.random()*120,s:.65+Math.random()*.75});
}
function resetGame(){score=0;coinCount=0;lives=3;timeLeft=300;camera=0;player.x=75;player.y=GROUND-player.h;player.vx=player.vy=0;player.coinsBoost=0;player.invuln=0;buildWorld();updateHud();mode='play';ui.overlay.classList.add('hidden');last=performance.now();playSound('start');}
function updateHud(){ui.score.textContent=String(score).padStart(6,'0');ui.coins.textContent=String(coinCount).padStart(2,'0');ui.lives.textContent='♥ '.repeat(Math.max(0,lives)).trim()||'—';ui.time.textContent=String(Math.max(0,Math.ceil(timeLeft))).padStart(3,'0');}
function showOverlay(title,subtitle,button,caption,kind){
  mode=kind;ui.overlay.classList.remove('hidden');
  ui.card.innerHTML=`<div class="eyebrow"><span>✦</span> ${caption} <span>✦</span></div><h1>${title}</h1><p class="story">${subtitle}</p><button id="primaryButton" class="primary-button"><span>▶</span> ${button}</button><div class="controls-note"><span>← →</span> MOVE <i>·</i> <span>SHIFT</span> RUN <i>·</i> <span>SPACE</span> JUMP</div><div class="menu-foot">FINAL SCORE &nbsp; ${String(score).padStart(6,'0')} &nbsp; · &nbsp; COINS ${coinCount}</div>`;
  ui.button=document.getElementById('primaryButton');ui.button.addEventListener('click',()=>{unlockAudio();if(kind==='victory')resetGame();else resetGame();});
}
function unlockAudio(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();}if(audio.state==='suspended')audio.resume();}
function tone(freq,duration=.11,type='square',volume=.035,when=0){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime+when);g.gain.setValueAtTime(volume,audio.currentTime+when);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+when+duration);o.connect(g);g.connect(audio.destination);o.start(audio.currentTime+when);o.stop(audio.currentTime+when+duration+.01);}
function playSound(name){if(!audio||muted)return;const tunes={coin:[[880,.08],[1320,.12]],jump:[[390,.08],[590,.12]],bump:[[230,.08],[175,.11]],stomp:[[170,.08],[540,.12]],power:[[523,.1],[659,.1],[784,.1],[1046,.2]],death:[[390,.12],[310,.15],[220,.25]],win:[[523,.12],[659,.12],[784,.12],[1046,.35]],start:[[392,.08],[523,.08],[659,.15]]};(tunes[name]||[]).forEach(([f,d],i)=>tone(f,d,'square',.04,i*.09));}
function addBurst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:-50-Math.random()*170,life:.45+Math.random()*.45,color,size:3+Math.random()*4});}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function collectCoin(c){c.taken=true;coinCount++;score+=100;player.coinsBoost=Math.min(8,player.coinsBoost+1);updateHud();playSound('coin');addBurst(c.x,c.y,'#ffd65d',5);}
function hitBlock(b){if(b.used)return;b.bump=1;score+=50;updateHud();playSound('bump');addBurst(b.x+b.w/2,b.y,'#f8cb58',4);if(Math.random()<.58){for(let i=0;i<1+(Math.random()<.24?1:0);i++){coins.push({x:b.x+b.w/2+i*11-6,y:b.y-14,r:9,taken:false,phase:0,bonus:true,vy:-260});}playSound('coin');}else{powerups.push({x:b.x+4,y:b.y-28,w:26,h:26,vx:70,vy:-210,type:'mushroom'});}b.used=true;}
function hurtPlayer(){if(player.invuln>0)return;lives--;updateHud();playSound('death');player.invuln=1.5;player.vy=-520;player.vx=-player.facing*190;if(lives<=0){setTimeout(()=>showOverlay('GAME<br>OVER','The trail can be tricky. Every great adventurer gets another try.','TRY AGAIN','NICE TRY, HERO','gameover'),650);}}
function finish(){if(mode!=='play')return;score+=Math.ceil(timeLeft)*10;updateHud();playSound('win');showOverlay('YOU DID<br>IT!','The Star Gate is yours. The whole kingdom is cheering for you!','PLAY AGAIN','A NEW LEGEND','victory');}
function update(dt){worldTime+=dt;if(messageTimer>0)messageTimer-=dt;
  if(mode!=='play'){return;}
  timeLeft-=dt;if(timeLeft<=0){timeLeft=0;updateHud();hurtPlayer();timeLeft=300;return;}
  player.anim+=dt*(Math.abs(player.vx)>.1?Math.abs(player.vx)/22:2);if(player.invuln>0)player.invuln-=dt;
  const accel=keys.run?1700:1250,max=keys.run?330:215,dir=(keys.right?1:0)-(keys.left?1:0);
  if(dir){player.vx+=dir*accel*dt;player.vx=Math.max(-max,Math.min(max,player.vx));player.facing=dir;}else player.vx*=Math.pow(player.grounded?.0001:.82,dt*60);
  if(keys.jump&&player.grounded){player.vy=-(565+Math.min(player.coinsBoost,6)*17);player.grounded=false;playSound('jump');}
  // Letting go early cuts the jump, while held jumps get a buoyant arc.
  if(!keys.jump&&player.vy< -100)player.vy+=GRAVITY*1.12*dt;else player.vy+=GRAVITY*dt;
  player.x+=player.vx*dt;player.x=Math.max(0,Math.min(LEVEL-player.w,player.x));
  const oldY=player.y;player.y+=player.vy*dt;player.grounded=false;
  for(const p of platforms){if(player.x+player.w>p.x&&player.x<p.x+p.w){if(player.vy>=0&&oldY+player.h<=p.y+4&&player.y+player.h>=p.y){player.y=p.y-player.h;player.vy=0;player.grounded=true;}else if(player.vy<0&&oldY>=p.y+p.h-2&&player.y<p.y+p.h&&p.h>24){player.y=p.y+p.h;player.vy=70;for(const b of blocks){if(Math.abs((b.x+b.w/2)-(player.x+player.w/2))<35&&Math.abs((b.y+b.h)-player.y)<18)hitBlock(b);}}}}
  for(const b of blocks){if(b.bump>0)b.bump=Math.max(0,b.bump-dt*4);if(player.vy<0&&player.x+player.w>b.x&&player.x<b.x+b.w&&oldY>=b.y+b.h-3&&player.y<=b.y+b.h){player.y=b.y+b.h;player.vy=70;hitBlock(b);}}
  for(const c of coins){if(c.bonus&&!c.taken){c.y+=c.vy*dt;c.vy+=700*dt;if(c.vy>80)c.vy=80;}if(!c.taken&&overlaps({x:player.x,y:player.y,w:player.w,h:player.h},{x:c.x-c.r,y:c.y-c.r,w:c.r*2,h:c.r*2}))collectCoin(c);}
  for(const p of powerups){if(!p.alive){p.vy+=GRAVITY*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;for(const s of platforms)if(p.x+p.w>s.x&&p.x<s.x+s.w&&p.y+p.h>=s.y&&p.y+p.h-p.vy*dt<=s.y){p.y=s.y-p.h;p.vy=0;}if(p.y>H+camera+150)p.alive=true;if(overlaps(player,p)){p.alive=true;score+=500;player.coinsBoost=Math.min(8,player.coinsBoost+2);updateHud();playSound('power');addBurst(p.x,p.y,'#ff836d',15);}}}
  for(const e of enemies){if(!e.alive)continue;e.x+=e.vx*dt;if(e.x<e.min||e.x>e.max){e.vx*=-1;e.x=Math.max(e.min,Math.min(e.max,e.x));}const wasAbove=oldY+player.h<=e.y+9;if(overlaps(player,e)){if(player.vy>20&&wasAbove){e.alive=false;player.vy=-405;score+=200;updateHud();playSound('stomp');addBurst(e.x+e.w/2,e.y+15,'#ed7968',9);}else hurtPlayer();}}
  if(player.y>H+camera+40){player.y=-70;player.vy=0;hurtPlayer();player.y=GROUND-player.h;player.x=Math.max(camera+60,player.x-120);}
  if(player.x>LEVEL-160&&player.y<GROUND+10)finish();
  camera=Math.max(0,Math.min(LEVEL-W,player.x-W*.38));
  particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=440*dt;p.life-=dt;}
}

function sky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#64b5ef');g.addColorStop(.63,'#b4e5f4');g.addColorStop(1,'#e2f5dc');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  // Warm sun and drifting clouds.
  const sunX=790-camera*.035;ctx.fillStyle='#ffe6a1';ctx.beginPath();ctx.arc(sunX,131,45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0bd55';ctx.beginPath();ctx.arc(sunX,131,62,0,Math.PI*2);ctx.fill();
  for(const c of clouds){let x=(c.x-camera*.18)%(LEVEL+500);if(x< -180)x+=LEVEL+500;x-=camera*.18%420;cloud(x,c.y,c.s);}
  // Faraway lavender mountains.
  ctx.fillStyle='#8cadd0';for(let i=-1;i<8;i++){const x=i*210-(camera*.27%210);ctx.beginPath();ctx.moveTo(x,390);ctx.lineTo(x+95,236+(i%3)*20);ctx.lineTo(x+205,390);ctx.closePath();ctx.fill();}
  ctx.fillStyle='#769ec5';for(let i=-1;i<7;i++){const x=i*280-(camera*.39%280);ctx.beginPath();ctx.moveTo(x,422);ctx.lineTo(x+125,280+(i%2)*30);ctx.lineTo(x+288,422);ctx.closePath();ctx.fill();}
  // Puffy green hills, drifting at a slower parallax.
  for(let i=-1;i<10;i++){let x=i*150-(camera*.56%150);ctx.fillStyle=i%2?'#8fceaa':'#9bd8aa';ctx.beginPath();ctx.ellipse(x+58,454,100,61,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(x-42,454,200,30);}
}
function cloud(x,y,s){ctx.fillStyle='#ffffffb8';ctx.beginPath();ctx.ellipse(x,y,30*s,12*s,0,0,Math.PI*2);ctx.ellipse(x+20*s,y-9*s,20*s,17*s,0,0,Math.PI*2);ctx.ellipse(x+43*s,y,27*s,12*s,0,0,Math.PI*2);ctx.fill();}
function drawGround(){
  const segments=[[0,660],[760,1410],[1510,2200],[2300,3080],[3190,3910],[4040,4750],[4860,6100]];
  for(const [a,b] of segments){const x=a-camera,w=b-a;ctx.fillStyle='#b8794e';ctx.fillRect(x,GROUND,w,H-GROUND);ctx.fillStyle='#d4935f';ctx.fillRect(x,GROUND+7,w,9);ctx.fillStyle='#85c86a';ctx.fillRect(x,GROUND,w,12);ctx.fillStyle='#b7e27b';ctx.fillRect(x,GROUND,w,4);
    for(let tx=Math.ceil(a/38)*38;tx<b;tx+=38){const sx=tx-camera;if((tx/38|0)%2===0){ctx.fillStyle='#9e6247';ctx.fillRect(sx,GROUND+22,18,14);ctx.fillStyle='#e3a06a';ctx.fillRect(sx+4,GROUND+25,10,3);}if((tx/76|0)%2===0){ctx.fillStyle='#ce8b59';ctx.fillRect(sx+20,GROUND+54,13,4);ctx.fillStyle='#91ce70';ctx.fillRect(sx+5,GROUND-2,3,7);}}
  }
  // Deep, shaded hazard pits with tiny glimmers.
  [[660,760],[1410,1510],[2200,2300],[3080,3190],[3910,4040],[4750,4860]].forEach(([a,b])=>{let x=a-camera;let gr=ctx.createLinearGradient(0,GROUND,0,H);gr.addColorStop(0,'#30456a');gr.addColorStop(1,'#192c4c');ctx.fillStyle=gr;ctx.fillRect(x,GROUND,b-a,H-GROUND);ctx.fillStyle='#263b5b';ctx.fillRect(x,GROUND,b-a,7);ctx.fillStyle='#ffd867';for(let j=0;j<3;j++){const xx=x+12+j*25+Math.sin(worldTime*2+j)*4;ctx.fillRect(xx,GROUND+74+j%2*37,3,3);}});
}
function drawPipes(){for(const p of [{x:680,w:58,h:72},{x:1370,w:64,h:105},{x:2210,w:62,h:80},{x:3100,w:72,h:112},{x:3950,w:62,h:76},{x:4770,w:68,h:100}]){const x=p.x-camera,y=GROUND-p.h;ctx.fillStyle='#31885f';ctx.fillRect(x,y+8,p.w,p.h-8);ctx.fillStyle='#50b879';ctx.fillRect(x+8,y+12,11,p.h-14);ctx.fillStyle='#256b53';ctx.fillRect(x+p.w-9,y+10,9,p.h-12);ctx.fillStyle='#42a96e';ctx.fillRect(x-6,y,p.w+12,18);ctx.fillStyle='#79cf85';ctx.fillRect(x-3,y+3,p.w+6,4);ctx.fillStyle='#29714f';ctx.fillRect(x-6,y+16,p.w+12,3);}}
function drawPlatforms(){for(const p of platforms){if(p.y>=GROUND)continue;const x=p.x-camera;if(x+p.w< -10||x>W+10)continue;ctx.fillStyle='#b97c51';ctx.fillRect(x,p.y+9,p.w,p.h-9);ctx.fillStyle='#83c96d';ctx.fillRect(x,p.y,p.w,10);ctx.fillStyle='#b4e27a';ctx.fillRect(x,p.y,p.w,3);for(let xx=0;xx<p.w;xx+=34){ctx.fillStyle='#9c6247';ctx.fillRect(x+xx+4,p.y+19,22,4);ctx.fillStyle='#d79662';ctx.fillRect(x+xx+10,p.y+25,12,3);}}
}
function drawBlocks(){for(const b of blocks){const x=b.x-camera,y=b.y-(b.bump?Math.sin(b.bump*Math.PI)*7:0);ctx.fillStyle=b.used?'#a87851':'#e99b46';ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle=b.used?'#c08c5c':'#ffc45c';ctx.fillRect(x+3,y+3,b.w-6,b.h-7);ctx.fillStyle=b.used?'#98694a':'#d8843e';ctx.fillRect(x,y+b.h-5,b.w,5);if(!b.used){ctx.fillStyle='#fff0b0';ctx.font='bold 24px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('?',x+b.w/2,y+b.h/2+1);ctx.fillStyle='#fff6d4';ctx.fillRect(x+5,y+5,5,4);}else{ctx.fillStyle='#d1a372';ctx.fillRect(x+6,y+7,22,4);ctx.fillRect(x+6,y+18,22,4);}}}
function drawCoins(){for(const c of coins){if(c.taken)continue;const x=c.x-camera,y=c.y+(c.bonus?0:Math.sin(worldTime*5+c.phase)*3);const thin=Math.max(.22,Math.abs(Math.cos(worldTime*5+c.phase)));ctx.save();ctx.translate(x,y);ctx.scale(thin,1);ctx.fillStyle='#bd752d';ctx.beginPath();ctx.ellipse(1,2,c.r*.85,c.r,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd044';ctx.beginPath();ctx.ellipse(0,0,c.r*.75,c.r,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff09a';ctx.fillRect(-2,-6,3,9);ctx.fillStyle='#f9ac36';ctx.fillRect(2,-5,2,11);ctx.restore();}}
function drawEnemies(){for(const e of enemies){if(!e.alive)continue;const x=e.x-camera,y=e.y;ctx.fillStyle='#702f4d';ctx.fillRect(x+3,y+8,26,19);ctx.fillStyle='#a94958';ctx.fillRect(x+5,y+4,22,20);ctx.fillStyle='#e87d69';ctx.fillRect(x+8,y+1,15,12);ctx.fillStyle='#fff0cc';ctx.fillRect(x+9,y+9,5,6);ctx.fillRect(x+20,y+9,5,6);ctx.fillStyle='#362c49';ctx.fillRect(x+11,y+11,2,4);ctx.fillRect(x+22,y+11,2,4);ctx.fillStyle='#593349';ctx.fillRect(x+5,y+23,9,6);ctx.fillRect(x+20,y+23,9,6);ctx.fillStyle='#ffbc74';ctx.fillRect(x+5,y+6,22,3);}}
function drawPowerups(){for(const p of powerups){if(p.alive)continue;const x=p.x-camera,y=p.y;ctx.fillStyle='#db6858';ctx.fillRect(x+2,y,22,13);ctx.fillStyle='#f78a68';ctx.fillRect(x+5,y-3,16,6);ctx.fillStyle='#fff1ca';ctx.fillRect(x+7,y+13,12,11);ctx.fillStyle='#583b51';ctx.fillRect(x+8,y+10,3,4);ctx.fillRect(x+17,y+10,3,4);ctx.fillStyle='#ffcc73';ctx.fillRect(x+2,y+22,22,4);}}

function drawPlayer(){if(player.invuln>0&&Math.floor(worldTime*14)%2===0)return;const x=Math.round(player.x-camera),y=Math.round(player.y),step=Math.sin(player.anim)*3,face=player.facing;
  // Shadow
  ctx.fillStyle='#2539583d';ctx.beginPath();ctx.ellipse(x+14,GROUND-2,19,4,0,0,Math.PI*2);ctx.fill();
  ctx.save();if(face<0){ctx.translate(x+player.w,0);ctx.scale(-1,1);}else ctx.translate(x,0);
  const leg=player.grounded?step:0;
  // Shoes and overalls
  ctx.fillStyle='#3d344e';ctx.fillRect(4,y+32+Math.max(0,leg),9,6);ctx.fillRect(17,y+32+Math.max(0,-leg),9,6);
  ctx.fillStyle='#3d72bd';ctx.fillRect(6,y+22,18,12);ctx.fillStyle='#548bd2';ctx.fillRect(8,y+24,6,9);ctx.fillRect(17,y+24,5,8);ctx.fillStyle='#ffe18a';ctx.fillRect(10,y+24,3,3);ctx.fillRect(19,y+24,3,3);
  // Face, ears, hair and cap
  ctx.fillStyle='#f0a66f';ctx.fillRect(7,y+10,18,15);ctx.fillRect(4,y+15,4,7);ctx.fillStyle='#ffe0a2';ctx.fillRect(9,y+13,13,9);ctx.fillStyle='#47394c';ctx.fillRect(18,y+15,3,4);ctx.fillRect(12,y+21,7,2);
  ctx.fillStyle='#6b3f42';ctx.fillRect(8,y+7,17,7);ctx.fillRect(10,y+4,13,5);ctx.fillStyle='#ef765f';ctx.fillRect(5,y+5,19,7);ctx.fillRect(3,y+10,22,4);ctx.fillStyle='#ffd176';ctx.fillRect(8,y+6,10,3);
  // Arms / gloves
  ctx.fillStyle='#f2ad78';ctx.fillRect(2,y+20,5,9);ctx.fillStyle='#fff0ce';ctx.fillRect(1,y+27,7,5);ctx.fillStyle='#f2ad78';ctx.fillRect(23,y+19,4,9);ctx.fillStyle='#fff0ce';ctx.fillRect(22,y+26,7,5);
  ctx.restore();}
function drawFlag(){const x=5810-camera;ctx.fillStyle='#f5ecd0';ctx.fillRect(x,212,7,GROUND-212);ctx.fillStyle='#b89367';ctx.fillRect(x-4,GROUND-7,16,7);ctx.fillStyle='#ffce62';ctx.beginPath();ctx.arc(x+3,207,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f27170';ctx.beginPath();ctx.moveTo(x+7,220);ctx.lineTo(x+83,237);ctx.lineTo(x+7,258);ctx.closePath();ctx.fill();ctx.fillStyle='#ffd68a';ctx.fillRect(x+8,226,49,4);ctx.fillStyle='#fff1cf';ctx.fillRect(x+7,220,4,38);}
function drawSparkles(){for(let i=0;i<8;i++){const x=((i*137+worldTime*17)%W),y=112+(i*61)%290;ctx.globalAlpha=.35+Math.sin(worldTime*2+i)*.22;ctx.fillStyle='#fff3c7';ctx.fillRect(x,y,2,2);}ctx.globalAlpha=1;}
function render(){ctx.clearRect(0,0,W,H);sky();drawSparkles();drawGround();drawPipes();drawPlatforms();drawBlocks();drawCoins();drawFlag();drawEnemies();drawPowerups();drawPlayer();
  for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x-camera,p.y,p.size,p.size);}ctx.globalAlpha=1;
  if(messageTimer>0){ctx.fillStyle='#183052d9';ctx.fillRect(W/2-115,92,230,30);ctx.fillStyle='#fff0c8';ctx.textAlign='center';ctx.font='12px monospace';ctx.fillText(screenMessage,W/2,112);}
}
const audioLine=[659,0,784,0,988,784,659,0,587,0,659,0,784,0,523,0,587,0,659,784,880,0,784,0,659,0,587,0,523,0,587,0];let beat=0,musicClock=0;
function frame(now){const dt=Math.min(.032,(now-last)/1000||0);last=now;update(dt);if(mode==='play'&&!muted&&audio){musicClock+=dt;if(musicClock>.2){musicClock-=.2;const n=audioLine[beat++%audioLine.length];if(n)tone(n,.14,'square',.012);}}render();requestAnimationFrame(frame);}
function press(code,on){if(code==='ArrowLeft'||code==='KeyA')keys.left=on;if(code==='ArrowRight'||code==='KeyD')keys.right=on;if(code==='ShiftLeft'||code==='ShiftRight'||code==='KeyX')keys.run=on;if(code==='Space'||code==='ArrowUp'||code==='KeyW'||code==='KeyZ'){if(on&&!keys.jump&&mode==='play'){keys.jump=true;}else if(!on)keys.jump=false;}}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyM'){muted=!muted;updateSoundButton();}if(e.code==='Enter'&&(mode==='menu'||mode==='gameover'||mode==='victory')){unlockAudio();resetGame();}press(e.code,true);});
window.addEventListener('keyup',e=>press(e.code,false));window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);});
function updateSoundButton(){ui.sound.innerHTML=`♫ <span>${muted?'SOUND OFF':'SOUND ON'}</span>`;ui.sound.setAttribute('aria-label',muted?'Turn sound on':'Turn sound off');}
ui.sound.addEventListener('click',()=>{unlockAudio();muted=!muted;updateSoundButton();});
ui.button.addEventListener('click',()=>{unlockAudio();resetGame();});
document.querySelectorAll('.touch-controls button').forEach(button=>{const code=button.dataset.key;const keyCode=code==='left'?'ArrowLeft':code==='right'?'ArrowRight':code==='run'?'ShiftLeft':'Space';const down=e=>{e.preventDefault();unlockAudio();button.classList.add('pressed');press(keyCode,true);};const up=e=>{e.preventDefault();button.classList.remove('pressed');press(keyCode,false);};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);});
buildWorld();updateHud();last=performance.now();requestAnimationFrame(frame);
})();

