(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=540,GROUND=458,LEVEL=6100,GRAVITY=1750;
const ui={overlay:document.getElementById('overlay'),card:document.getElementById('overlayCard'),button:document.getElementById('primaryButton'),score:document.getElementById('score'),coins:document.getElementById('coins'),lives:document.getElementById('lives'),time:document.getElementById('time'),sound:document.getElementById('soundToggle')};
let mode='menu',last=0,camera=0,score=0,coinCount=0,lives=3,timeLeft=300,muted=false,audio=null,worldTime=0,messageTimer=0;
const keys={left:false,right:false,run:false,jump:false};
const player={x:75,y:GROUND-38,w:28,h:38,vx:0,vy:0,grounded:false,facing:1,coinsBoost:0,invuln:0,anim:0};
let platforms=[],blocks=[],coins=[],enemies=[],powerups=[],particles=[],clouds=[];
const rect=(x,y,w,h)=>({x,y,w,h});
function buildWorld(){
 platforms=[rect(0,458,660,100),rect(760,458,650,100),rect(1510,458,690,100),rect(2300,458,780,100),rect(3190,458,720,100),rect(4040,458,710,100),rect(4860,458,1240,100)];
 [[230,355,124],[415,295,112],[570,365,92],[880,350,112],[1050,285,112],[1238,350,114],[1570,345,126],[1760,285,110],[1930,360,112],[2390,350,108],[2555,290,105],[2720,230,105],[2860,345,115],[3280,350,110],[3450,290,110],[3630,350,112],[4140,350,110],[4310,290,112],[4490,350,110],[4970,350,110],[5150,290,108],[5335,350,110],[5520,280,112]].forEach(([x,y,w])=>platforms.push(rect(x,y,w,20)));
 [{x:680,w:58,h:72},{x:1370,w:64,h:105},{x:2210,w:62,h:80},{x:3100,w:72,h:112},{x:3950,w:62,h:76},{x:4770,w:68,h:100}].forEach(p=>platforms.push(rect(p.x,458-p.h,p.w,p.h)));
 blocks=[];[[278,355,'?'],[314,355,'b'],[455,295,'?'],[920,350,'?'],[1090,285,'?'],[1635,345,'?'],[1797,285,'?'],[2475,350,'?'],[2600,290,'?'],[3335,350,'?'],[3500,290,'?'],[4200,350,'?'],[4370,290,'?'],[5060,350,'?'],[5230,290,'?']].forEach(([x,y,type])=>blocks.push({x,y,w:34,h:34,type,used:false,bump:0}));
 coins=[];const add=(x,y)=>coins.push({x,y,r:10,taken:false,phase:Math.random()*6});
 [[185,400],[233,315],[271,315],[309,315],[416,255],[455,255],[494,255],[568,325],[826,405],[880,310],[920,310],[960,310],[1050,245],[1090,245],[1130,245],[1240,310],[1515,410],[1570,305],[1610,305],[1650,305],[1760,245],[1800,245],[1840,245],[1970,320],[2370,410],[2390,310],[2430,310],[2470,310],[2555,250],[2595,250],[2635,250],[2720,190],[2860,305],[2900,305],[3210,410],[3280,310],[3320,310],[3360,310],[3450,250],[3490,250],[3530,250],[3630,310],[4060,410],[4140,310],[4180,310],[4220,310],[4310,250],[4350,250],[4390,250],[4490,310],[4910,410],[4970,310],[5010,310],[5050,310],[5150,250],[5190,250],[5230,250],[5335,310],[5520,240],[5560,240],[5600,240]].forEach(([x,y])=>add(x,y));
 enemies=[];[510,990,1290,1840,2040,2460,2790,3500,3740,4260,4580,5090,5390].forEach((x,i)=>enemies.push({x,y:428,w:32,h:30,vx:(i%2?1:-1)*48,min:x-90,max:x+90,alive:true}));
 powerups=[];particles=[];clouds=[];for(let i=0;i<18;i++)clouds.push({x:i*420+Math.random()*220,y:55+Math.random()*120,s:.65+Math.random()*.75});
}
function updateHud(){ui.score.textContent=String(score).padStart(6,'0');ui.coins.textContent=String(coinCount).padStart(2,'0');ui.lives.textContent='♥ '.repeat(Math.max(0,lives)).trim()||'—';ui.time.textContent=String(Math.max(0,Math.ceil(timeLeft))).padStart(3,'0');}
function resetGame(){score=0;coinCount=0;lives=3;timeLeft=300;camera=0;player.x=75;player.y=GROUND-player.h;player.vx=player.vy=0;player.coinsBoost=0;player.invuln=0;buildWorld();updateHud();mode='play';ui.overlay.classList.add('hidden');last=performance.now();playSound('start');}
function showOverlay(title,subtitle,button,caption,kind){mode=kind;ui.overlay.classList.remove('hidden');ui.card.innerHTML=`<div class="eyebrow"><span>✦</span> ${caption} <span>✦</span></div><h1>${title}</h1><p class="story">${subtitle}</p><button id="primaryButton" class="primary-button"><span>▶</span> ${button}</button><div class="controls-note"><span>← →</span> MOVE <i>·</i> <span>SHIFT</span> RUN <i>·</i> <span>SPACE</span> JUMP</div><div class="menu-foot">FINAL SCORE &nbsp; ${String(score).padStart(6,'0')} &nbsp; · &nbsp; COINS ${coinCount}</div>`;ui.button=document.getElementById('primaryButton');ui.button.addEventListener('click',()=>{unlockAudio();resetGame();});}
function unlockAudio(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();}
function tone(freq,duration=.11,type='square',volume=.035,when=0){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime+when);g.gain.setValueAtTime(volume,audio.currentTime+when);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+when+duration);o.connect(g);g.connect(audio.destination);o.start(audio.currentTime+when);o.stop(audio.currentTime+when+duration+.01);}
function playSound(name){if(!audio||muted)return;const t={coin:[[880,.08],[1320,.12]],jump:[[390,.08],[590,.12]],bump:[[230,.08],[175,.11]],stomp:[[170,.08],[540,.12]],power:[[523,.1],[659,.1],[784,.1],[1046,.2]],death:[[390,.12],[310,.15],[220,.25]],win:[[523,.12],[659,.12],[784,.12],[1046,.35]],start:[[392,.08],[523,.08],[659,.15]]};(t[name]||[]).forEach(([f,d],i)=>tone(f,d,'square',.04,i*.09));}
function addBurst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:-50-Math.random()*170,life:.45+Math.random()*.45,color,size:3+Math.random()*4});}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function collectCoin(c){c.taken=true;coinCount++;score+=100;player.coinsBoost=Math.min(8,player.coinsBoost+1);updateHud();playSound('coin');addBurst(c.x,c.y,'#ffd65d',5);}
function hitBlock(b){if(b.used)return;b.bump=1;score+=50;updateHud();playSound('bump');addBurst(b.x+b.w/2,b.y,'#f8cb58',4);if(Math.random()<.58){for(let i=0;i<1+(Math.random()<.24?1:0);i++)coins.push({x:b.x+b.w/2+i*11-6,y:b.y-14,r:9,taken:false,phase:0,bonus:true,vy:-260});}else powerups.push({x:b.x+4,y:b.y-28,w:26,h:26,vx:70,vy:-210,type:'mushroom'});b.used=true;}
function hurtPlayer(){if(player.invuln>0)return;lives--;updateHud();playSound('death');player.invuln=1.5;player.vy=-520;player.vx=-player.facing*190;if(lives<=0)setTimeout(()=>showOverlay('GAME<br>OVER','The trail can be tricky. Every great adventurer gets another try.','TRY AGAIN','NICE TRY, HERO','gameover'),650);}
function finish(){if(mode!=='play')return;score+=Math.ceil(timeLeft)*10;updateHud();playSound('win');showOverlay('YOU DID<br>IT!','The Star Gate is yours. The whole kingdom is cheering for you!','PLAY AGAIN','A NEW LEGEND','victory');}
function update(dt){worldTime+=dt;if(mode!=='play')return;timeLeft-=dt;if(timeLeft<=0){timeLeft=300;hurtPlayer();return;}player.anim+=dt*(Math.abs(player.vx)>.1?Math.abs(player.vx)/22:2);if(player.invuln>0)player.invuln-=dt;
 const accel=keys.run?1700:1250,max=keys.run?330:215,dir=(keys.right?1:0)-(keys.left?1:0);if(dir){player.vx+=dir*accel*dt;player.vx=Math.max(-max,Math.min(max,player.vx));player.facing=dir;}else player.vx*=Math.pow(player.grounded?.0001:.82,dt*60);
 if(keys.jump&&player.grounded){player.vy=-(565+Math.min(player.coinsBoost,6)*17);player.grounded=false;playSound('jump');}if(!keys.jump&&player.vy< -100)player.vy+=GRAVITY*1.12*dt;else player.vy+=GRAVITY*dt;
 player.x=Math.max(0,Math.min(LEVEL-player.w,player.x+player.vx*dt));const oldY=player.y;player.y+=player.vy*dt;player.grounded=false;
 for(const p of platforms){if(player.x+player.w>p.x&&player.x<p.x+p.w){if(player.vy>=0&&oldY+player.h<=p.y+4&&player.y+player.h>=p.y){player.y=p.y-player.h;player.vy=0;player.grounded=true;}else if(player.vy<0&&oldY>=p.y+p.h-2&&player.y<p.y+p.h&&p.h>24){player.y=p.y+p.h;player.vy=70;}}}
 for(const b of blocks){if(b.bump>0)b.bump=Math.max(0,b.bump-dt*4);if(player.vy<0&&player.x+player.w>b.x&&player.x<b.x+b.w&&oldY>=b.y+b.h-3&&player.y<=b.y+b.h){player.y=b.y+b.h;player.vy=70;hitBlock(b);}}
 for(const c of coins){if(c.bonus&&!c.taken){c.y+=c.vy*dt;c.vy+=700*dt;if(c.vy>80)c.vy=80;}if(!c.taken&&overlaps(player,{x:c.x-c.r,y:c.y-c.r,w:c.r*2,h:c.r*2}))collectCoin(c);}
 for(const p of powerups){if(p.alive)continue;p.vy+=GRAVITY*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;for(const s of platforms)if(p.x+p.w>s.x&&p.x<s.x+s.w&&p.y+p.h>=s.y&&p.y+p.h-p.vy*dt<=s.y){p.y=s.y-p.h;p.vy=0;}if(p.y>H+camera+150)p.alive=true;if(overlaps(player,p)){p.alive=true;score+=500;player.coinsBoost=Math.min(8,player.coinsBoost+2);updateHud();playSound('power');addBurst(p.x,p.y,'#ff836d',15);}}
 for(const e of enemies){if(!e.alive)continue;e.x+=e.vx*dt;if(e.x<e.min||e.x>e.max){e.vx*=-1;e.x=Math.max(e.min,Math.min(e.max,e.x));}if(overlaps(player,e)){if(player.vy>20&&oldY+player.h<=e.y+9){e.alive=false;player.vy=-405;score+=200;updateHud();playSound('stomp');addBurst(e.x+e.w/2,e.y+15,'#ed7968',9);}else hurtPlayer();}}
 if(player.y>H+camera+40){player.y=GROUND-player.h;player.vy=0;hurtPlayer();player.x=Math.max(camera+60,player.x-120);}if(player.x>LEVEL-160)finish();camera=Math.max(0,Math.min(LEVEL-W,player.x-W*.38));particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=440*dt;p.life-=dt;}
}
