function sky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#64b5ef');g.addColorStop(.63,'#b4e5f4');g.addColorStop(1,'#e2f5dc');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const sx=790-camera*.035;ctx.fillStyle='#ffe6a1';ctx.beginPath();ctx.arc(sx,131,45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0bd55';ctx.beginPath();ctx.arc(sx,131,62,0,Math.PI*2);ctx.fill();for(const c of clouds){let x=(c.x-camera*.18)%(LEVEL+500);if(x< -180)x+=LEVEL+500;cloud(x-camera*.18%420,c.y,c.s);}ctx.fillStyle='#8cadd0';for(let i=-1;i<8;i++){const x=i*210-camera*.27%210;ctx.beginPath();ctx.moveTo(x,390);ctx.lineTo(x+95,236+(i%3)*20);ctx.lineTo(x+205,390);ctx.fill();}ctx.fillStyle='#769ec5';for(let i=-1;i<7;i++){const x=i*280-camera*.39%280;ctx.beginPath();ctx.moveTo(x,422);ctx.lineTo(x+125,280+(i%2)*30);ctx.lineTo(x+288,422);ctx.fill();}for(let i=-1;i<10;i++){let x=i*150-camera*.56%150;ctx.fillStyle=i%2?'#8fceaa':'#9bd8aa';ctx.beginPath();ctx.ellipse(x+58,454,100,61,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(x-42,454,200,30);}}
function cloud(x,y,s){ctx.fillStyle='#ffffffb8';ctx.beginPath();ctx.ellipse(x,y,30*s,12*s,0,0,7);ctx.ellipse(x+20*s,y-9*s,20*s,17*s,0,0,7);ctx.ellipse(x+43*s,y,27*s,12*s,0,0,7);ctx.fill();}
function drawGround(){for(const [a,b] of [[0,660],[760,1410],[1510,2200],[2300,3080],[3190,3910],[4040,4750],[4860,6100]]){const x=a-camera,w=b-a;ctx.fillStyle='#b8794e';ctx.fillRect(x,458,w,H-458);ctx.fillStyle='#d4935f';ctx.fillRect(x,465,w,9);ctx.fillStyle='#85c86a';ctx.fillRect(x,458,w,12);ctx.fillStyle='#b7e27b';ctx.fillRect(x,458,w,4);for(let tx=Math.ceil(a/38)*38;tx<b;tx+=38){const sx=tx-camera;if((tx/38|0)%2===0){ctx.fillStyle='#9e6247';ctx.fillRect(sx,480,18,14);ctx.fillStyle='#e3a06a';ctx.fillRect(sx+4,483,10,3);}if((tx/76|0)%2===0){ctx.fillStyle='#ce8b59';ctx.fillRect(sx+20,512,13,4);ctx.fillStyle='#91ce70';ctx.fillRect(sx+5,456,3,7);}}}for(const [a,b] of [[660,760],[1410,1510],[2200,2300],[3080,3190],[3910,4040],[4750,4860]]){const x=a-camera,g=ctx.createLinearGradient(0,458,0,H);g.addColorStop(0,'#30456a');g.addColorStop(1,'#192c4c');ctx.fillStyle=g;ctx.fillRect(x,458,b-a,H-458);ctx.fillStyle='#263b5b';ctx.fillRect(x,458,b-a,7);ctx.fillStyle='#ffd867';for(let j=0;j<3;j++)ctx.fillRect(x+12+j*25+Math.sin(worldTime*2+j)*4,532+j%2*37,3,3);}}
function drawPipes(){for(const p of [{x:680,w:58,h:72},{x:1370,w:64,h:105},{x:2210,w:62,h:80},{x:3100,w:72,h:112},{x:3950,w:62,h:76},{x:4770,w:68,h:100}]){const x=p.x-camera,y=458-p.h;ctx.fillStyle='#31885f';ctx.fillRect(x,y+8,p.w,p.h-8);ctx.fillStyle='#50b879';ctx.fillRect(x+8,y+12,11,p.h-14);ctx.fillStyle='#256b53';ctx.fillRect(x+p.w-9,y+10,9,p.h-12);ctx.fillStyle='#42a96e';ctx.fillRect(x-6,y,p.w+12,18);ctx.fillStyle='#79cf85';ctx.fillRect(x-3,y+3,p.w+6,4);ctx.fillStyle='#29714f';ctx.fillRect(x-6,y+16,p.w+12,3);}}
function drawPlatforms(){for(const p of platforms){if(p.y>=458)continue;const x=p.x-camera;if(x+p.w< -10||x>W+10)continue;ctx.fillStyle='#b97c51';ctx.fillRect(x,p.y+9,p.w,p.h-9);ctx.fillStyle='#83c96d';ctx.fillRect(x,p.y,p.w,10);ctx.fillStyle='#b4e27a';ctx.fillRect(x,p.y,p.w,3);for(let xx=0;xx<p.w;xx+=34){ctx.fillStyle='#9c6247';ctx.fillRect(x+xx+4,p.y+19,22,4);ctx.fillStyle='#d79662';ctx.fillRect(x+xx+10,p.y+25,12,3);}}}
function drawBlocks(){for(const b of blocks){const x=b.x-camera,y=b.y-(b.bump?Math.sin(b.bump*Math.PI)*7:0);ctx.fillStyle=b.used?'#a87851':'#e99b46';ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle=b.used?'#c08c5c':'#ffc45c';ctx.fillRect(x+3,y+3,b.w-6,b.h-7);ctx.fillStyle=b.used?'#98694a':'#d8843e';ctx.fillRect(x,y+b.h-5,b.w,5);if(!b.used){ctx.fillStyle='#fff0b0';ctx.font='bold 24px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('?',x+b.w/2,y+b.h/2+1);ctx.fillStyle='#fff6d4';ctx.fillRect(x+5,y+5,5,4);}else{ctx.fillStyle='#d1a372';ctx.fillRect(x+6,y+7,22,4);ctx.fillRect(x+6,y+18,22,4);}}}
function drawCoins(){for(const c of coins){if(c.taken)continue;const x=c.x-camera,y=c.y+(c.bonus?0:Math.sin(worldTime*5+c.phase)*3),thin=Math.max(.22,Math.abs(Math.cos(worldTime*5+c.phase)));ctx.save();ctx.translate(x,y);ctx.scale(thin,1);ctx.fillStyle='#bd752d';ctx.beginPath();ctx.ellipse(1,2,c.r*.85,c.r,0,0,7);ctx.fill();ctx.fillStyle='#ffd044';ctx.beginPath();ctx.ellipse(0,0,c.r*.75,c.r,0,0,7);ctx.fill();ctx.fillStyle='#fff09a';ctx.fillRect(-2,-6,3,9);ctx.fillStyle='#f9ac36';ctx.fillRect(2,-5,2,11);ctx.restore();}}
function drawEnemies(){for(const e of enemies){if(!e.alive)continue;const x=e.x-camera,y=e.y;ctx.fillStyle='#702f4d';ctx.fillRect(x+3,y+8,26,19);ctx.fillStyle='#a94958';ctx.fillRect(x+5,y+4,22,20);ctx.fillStyle='#e87d69';ctx.fillRect(x+8,y+1,15,12);ctx.fillStyle='#fff0cc';ctx.fillRect(x+9,y+9,5,6);ctx.fillRect(x+20,y+9,5,6);ctx.fillStyle='#362c49';ctx.fillRect(x+11,y+11,2,4);ctx.fillRect(x+22,y+11,2,4);ctx.fillStyle='#593349';ctx.fillRect(x+5,y+23,9,6);ctx.fillRect(x+20,y+23,9,6);ctx.fillStyle='#ffbc74';ctx.fillRect(x+5,y+6,22,3);}}
function drawPowerups(){for(const p of powerups){if(p.alive)continue;const x=p.x-camera,y=p.y;ctx.fillStyle='#db6858';ctx.fillRect(x+2,y,22,13);ctx.fillStyle='#f78a68';ctx.fillRect(x+5,y-3,16,6);ctx.fillStyle='#fff1ca';ctx.fillRect(x+7,y+13,12,11);ctx.fillStyle='#583b51';ctx.fillRect(x+8,y+10,3,4);ctx.fillRect(x+17,y+10,3,4);ctx.fillStyle='#ffcc73';ctx.fillRect(x+2,y+22,22,4);}}
function drawPlayer(){if(player.invuln>0&&Math.floor(worldTime*14)%2===0)return;const x=Math.round(player.x-camera),y=Math.round(player.y),step=Math.sin(player.anim)*3;ctx.fillStyle='#2539583d';ctx.beginPath();ctx.ellipse(x+14,456,19,4,0,0,7);ctx.fill();ctx.save();if(player.facing<0){ctx.translate(x+player.w,0);ctx.scale(-1,1);}else ctx.translate(x,0);const leg=player.grounded?step:0;ctx.fillStyle='#3d344e';ctx.fillRect(4,y+32+Math.max(0,leg),9,6);ctx.fillRect(17,y+32+Math.max(0,-leg),9,6);ctx.fillStyle='#3d72bd';ctx.fillRect(6,y+22,18,12);ctx.fillStyle='#548bd2';ctx.fillRect(8,y+24,6,9);ctx.fillRect(17,y+24,5,8);ctx.fillStyle='#ffe18a';ctx.fillRect(10,y+24,3,3);ctx.fillRect(19,y+24,3,3);ctx.fillStyle='#f0a66f';ctx.fillRect(7,y+10,18,15);ctx.fillRect(4,y+15,4,7);ctx.fillStyle='#ffe0a2';ctx.fillRect(9,y+13,13,9);ctx.fillStyle='#47394c';ctx.fillRect(18,y+15,3,4);ctx.fillRect(12,y+21,7,2);ctx.fillStyle='#6b3f42';ctx.fillRect(8,y+7,17,7);ctx.fillRect(10,y+4,13,5);ctx.fillStyle='#ef765f';ctx.fillRect(5,y+5,19,7);ctx.fillRect(3,y+10,22,4);ctx.fillStyle='#ffd176';ctx.fillRect(8,y+6,10,3);ctx.fillStyle='#f2ad78';ctx.fillRect(2,y+20,5,9);ctx.fillRect(23,y+19,4,9);ctx.fillStyle='#fff0ce';ctx.fillRect(1,y+27,7,5);ctx.fillRect(22,y+26,7,5);ctx.restore();}
function drawFlag(){const x=5810-camera;ctx.fillStyle='#f5ecd0';ctx.fillRect(x,212,7,GROUND-212);ctx.fillStyle='#b89367';ctx.fillRect(x-4,GROUND-7,16,7);ctx.fillStyle='#ffce62';ctx.beginPath();ctx.arc(x+3,207,8,0,7);ctx.fill();ctx.fillStyle='#f27170';ctx.beginPath();ctx.moveTo(x+7,220);ctx.lineTo(x+83,237);ctx.lineTo(x+7,258);ctx.closePath();ctx.fill();ctx.fillStyle='#ffd68a';ctx.fillRect(x+8,226,49,4);}
function render(){ctx.clearRect(0,0,W,H);sky();drawGround();drawPipes();drawPlatforms();drawBlocks();drawCoins();drawFlag();drawEnemies();drawPowerups();drawPlayer();for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x-camera,p.y,p.size,p.size);}ctx.globalAlpha=1;}

